  "Smooth": ["Weich", "Suave", "Lisse", "Suave", "Morbida"],
  "Something broke": ["Etwas ist kaputt", "Algo falló", "Quelque chose est cassé", "Algo quebrou", "Qualcosa si è rotto"],
  "Something is confusing": ["Etwas ist verwirrend", "Algo es confuso", "Quelque chose est déroutant", "Algo está confuso", "Qualcosa non è chiaro"],
  "Spelling": ["Rechtschreibung", "Ortografía", "Orthographe", "Ortografia", "Ortografia"],
  "Stamp": ["Stempel", "Sello", "Tampon", "Carimbo", "Timbro"],
