  "Undo": ["Rückgängig", "Deshacer", "Annuler", "Desfazer", "Annulla"],
  "Undo (Ctrl+Z)": ["Rückgängig (Strg+Z)", "Deshacer (Ctrl+Z)", "Annuler (Ctrl+Z)", "Desfazer (Ctrl+Z)", "Annulla (Ctrl+Z)"],
